"""Regenerate the module facade after replacing the vendored GLAD 1 header."""
from pathlib import Path
import re

root = Path(__file__).resolve().parents[1]
header = (root / 'vendor/glad/include/glad/glad.h').read_text()
aliases = re.findall(r'^#define (gl\w+) (glad_gl\w+)\s*$', header, re.M)
constants = dict(re.findall(r'^#define (GL_\w+) ([^\r\n]+)', header, re.M))
lines = [
    '// Generated by tools/generate_glad_module.py; do not edit.',
    'module;',
    '#include <KHR/khrplatform.h>',
    'export module glad;',
    'export {',
    '#include <glad/glad.h>',
    '}',
    '// Macros are local to this translation unit; expose C++ equivalents.',
]
for name, target in aliases:
    lines += [f'#undef {name}', f'export inline auto& {name} = {target};']
for name, value in constants.items():
    lines += [f'#undef {name}', f'export inline constexpr auto {name} = {value};']
(root / 'src/glad.cppm').write_text('\n'.join(lines) + '\n')
